<?php
declare(strict_types=1);
/** Retiro: exportação de autorização completa 2, CPF do responsável, e duas por A4. */
if (PHP_SAPI !== 'cli') { http_response_code(403); exit('Somente terminal.'); }
$raiz = __DIR__;
$acao = $argv[1] ?? '';
if (!in_array($acao, ['', '--verificar'], true) || $argc > 2) { fwrite(STDERR,"Uso: php aplicar_alteracao_autorizacao_completa2.php [--verificar]\n"); exit(1); }
$patches = json_decode(base64_decode(''), true, 512, JSON_THROW_ON_ERROR);
$novos = json_decode(base64_decode(''), true, 512, JSON_THROW_ON_ERROR);
function autFalhar(string $s): never { throw new RuntimeException($s); }
function autLer(string $p): string { $s=@file_get_contents($p); if($s===false) autFalhar('Falha na leitura: '.$p); return $s; }
function autLint(string $p): void {
    if (!function_exists('exec')) autFalhar('exec() indisponível para verificar sintaxe PHP.');
    $out=[]; $rc=-1; exec(escapeshellarg(PHP_BINARY).' -l '.escapeshellarg($p).' 2>&1',$out,$rc);
    if ($rc!==0) autFalhar('Sintaxe inválida: '.$p.' '.implode(' ',$out));
}
$alteracoes=[]; $staged=[]; $aplicados=[]; $backup='';
try {
    if (!is_file($raiz.'/config/settings.php') || !is_file($raiz.'/config/conn.php')) autFalhar('Coloque o instalador na raiz do sistema Retiro.');
    foreach($patches as $rel=>$regras) {
        $dest=$raiz.'/'.$rel;
        if (!is_file($dest) || is_link($dest)) autFalhar('Arquivo original não localizado ou link simbólico: '.$rel);
        $original=autLer($dest); $novo=$original;
        foreach($regras as [$marca,$antes,$depois]) {
            if (str_contains($novo,$marca)) continue;
            $q=substr_count($novo,$antes);
            if ($q!==1) autFalhar('Conflito / trecho ausente ou duplicado: '.$rel.' ['.$marca.'] ('.$q.'). Nenhuma alteração feita.');
            $novo=str_replace($antes,$depois,$novo);
        }
        if ($novo!==$original) $alteracoes[$rel]=[$original,$novo];
    }
    foreach($novos as $rel=>$codigo) {
        $dest=$raiz.'/'.$rel;
        if (is_link($dest)) autFalhar('Destino simbólico recusado: '.$rel);
        if (is_file($dest)) {
            if (autLer($dest)!==$codigo) autFalhar('Já existe um arquivo diferente em '.$rel);
            continue;
        }
        if(file_exists($dest)) autFalhar('Destino ocupado: '.$rel);
        $alteracoes[$rel]=[null,$codigo];
    }
    foreach($alteracoes as $rel=>[$original,$codigo]) {
        $dir=$raiz.'/'.dirname($rel);
        if(!is_dir($dir)) autFalhar('Diretório não encontrado: '.dirname($rel));
        $tmp=tempnam($dir,'.retiro-aut2-');
        if($tmp===false || file_put_contents($tmp,$codigo)!==strlen($codigo)) autFalhar('Não foi possível preparar: '.$rel);
        $staged[$rel]=$tmp; autLint($tmp);
        @chmod($tmp,$original!==null ? (fileperms($raiz.'/'.$rel)&0777) : 0644);
    }
    echo '[OK] Sintaxe de '.count($alteracoes).' arquivo(s) novo(s)/alterado(s) validada.'.PHP_EOL;
    if ($acao==='--verificar') {
        echo '[PRÉVIA] Alterações: '.implode(', ',array_keys($alteracoes)).PHP_EOL;
        echo '[PRÉVIA] Banco: será criada, se ausente, a coluna opcional inscricao_dados_adicionais.responsavel_cpf. Nenhuma alteração agora.'.PHP_EOL;
        foreach($staged as $tmp) @unlink($tmp);
        exit(0);
    }
    if (!$alteracoes) { echo '[OK] Código já instalado. Verifique a existência da coluna responsavel_cpf no banco.'.PHP_EOL; foreach($staged as $tmp) @unlink($tmp); exit(0); }
    $pastaBackup=dirname($raiz).'/backups-retiro';
    if(!is_dir($pastaBackup) && !mkdir($pastaBackup,0700,true)) autFalhar('Não foi possível criar pasta de backup.');
    $backup=$pastaBackup.'/autorizacao-completa2-'.date('Ymd-His').'-'.bin2hex(random_bytes(4));
    if(!mkdir($backup,0700,true)) autFalhar('Falha ao iniciar backup.');
    foreach($alteracoes as $rel=>[$original,$codigo]) {
        if($original!==null) {
            $dest=$backup.'/'.$rel;
            if(!is_dir(dirname($dest)) && !mkdir(dirname($dest),0700,true)) autFalhar('Falha ao criar pasta de backup.');
            if(file_put_contents($dest,$original)!==strlen($original)) autFalhar('Backup incompleto: '.$rel);
            @chmod($dest,0600);
        }
    }
    // DDL não faz rollback em MySQL; é uma coluna nova, opcional e não destrutiva.
    $cfg=require $raiz.'/config/conn.php';
    if(!is_array($cfg)||!isset($cfg['host'],$cfg['database'],$cfg['username'],$cfg['password'])) autFalhar('config/conn.php inválido.');
    $db=new PDO('mysql:host='.$cfg['host'].';dbname='.$cfg['database'].';charset='.($cfg['charset']??'utf8mb4'),$cfg['username'],$cfg['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
    $stmt=$db->query("SHOW COLUMNS FROM inscricao_dados_adicionais LIKE 'responsavel_cpf'");
    if (!$stmt->fetch(PDO::FETCH_ASSOC)) {
        $db->exec("ALTER TABLE inscricao_dados_adicionais ADD COLUMN responsavel_cpf VARCHAR(14) NULL AFTER responsavel_nome");
        echo '[OK] Coluna opcional de CPF do responsável criada; registros antigos preservados.'.PHP_EOL;
    } else { echo '[OK] Coluna responsavel_cpf já existe.'.PHP_EOL; }
    foreach($alteracoes as $rel=>[$original,$codigo]) {
        $dest=$raiz.'/'.$rel;
        if($original===null && file_exists($dest)) autFalhar('Conflito na instalação: '.$rel);
        if($original!==null && autLer($dest)!==$original) autFalhar('Arquivo mudou durante a instalação: '.$rel);
        if(!rename($staged[$rel],$dest)) autFalhar('Falha ao substituir: '.$rel);
        unset($staged[$rel]); $aplicados[]=$rel;
        echo '[OK] '.$rel.PHP_EOL;
    }
    echo '[OK] Instalação concluída. Exportação antiga preservada. Backup: '.$backup.PHP_EOL;
} catch(Throwable $e) {
    foreach(array_reverse($aplicados) as $rel) {
        $dest=$raiz.'/'.$rel; [$old,$new]=$alteracoes[$rel];
        if($old===null) @unlink($dest);
        else if(!@copy($backup.'/'.$rel,$dest)) fwrite(STDERR,'[AVISO] Restaure manualmente: '.$rel.PHP_EOL);
    }
    fwrite(STDERR,'[ERRO] '.$e->getMessage().PHP_EOL);
    if($backup!=='') fwrite(STDERR,'Backup: '.$backup.PHP_EOL);
    exit(1);
} finally { foreach($staged as $tmp) @unlink($tmp); }
